//! Real-ESRGAN in Burn: the models generated by build.rs, the tiling that
//! cuts a picture into same-sized pieces for them and back, and `Upscaler`,
//! one loaded model. The weights come as bytes (a downloaded .bpk file);
//! `web` is the same for a browser tab.

pub mod model {
    pub mod real_esrgan_general_x4v3 {
        include!(concat!(env!("OUT_DIR"), "/model/real_esrgan_general_x4v3.rs"));
    }
    pub mod real_esrgan_x4plus {
        include!(concat!(env!("OUT_DIR"), "/model/real_esrgan_x4plus.rs"));
    }
}

#[cfg(feature = "web")]
pub mod web;

use burn::prelude::*;
use burn::tensor::Bytes;

/// Every model here enlarges 4×.
pub const SCALE: usize = 4;
/// The largest picture taken in, in pixels (640 × 640): the result is 16 times
/// that, and travels back to the pool as one message.
pub const MAX_PIXELS: u64 = 640 * 640;
const TILE: usize = 112; // + 2 × PAD = 128 px, the fastest measured (plans/local-images.md)
const PAD: usize = 8;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Kind {
    Fast,
    Quality,
}

impl Kind {
    pub const ALL: [Kind; 2] = [Kind::Fast, Kind::Quality];
    /// The pool's name for it.
    pub fn name(self) -> &'static str {
        match self {
            Kind::Fast => "upscale-fast",
            Kind::Quality => "upscale-quality",
        }
    }
    /// Its weights' file name (in the pool's model list and on disk).
    pub fn file(self) -> &'static str {
        match self {
            Kind::Fast => "real_esrgan_general_x4v3.bpk",
            Kind::Quality => "real_esrgan_x4plus.bpk",
        }
    }
    pub fn from_name(name: &str) -> Option<Kind> {
        Kind::ALL.into_iter().find(|k| k.name() == name)
    }
}

/// The upscalers whose weights are in `dir` (downloaded and checked by the app).
#[cfg(not(target_family = "wasm"))]
pub fn available(dir: &std::path::Path) -> Vec<Kind> {
    Kind::ALL.into_iter().filter(|k| dir.join(k.file()).is_file()).collect()
}

#[cfg(not(target_family = "wasm"))]
type Forward = Box<dyn Fn(Tensor<4>) -> Tensor<4> + Send>;
#[cfg(target_family = "wasm")]
type Forward = Box<dyn Fn(Tensor<4>) -> Tensor<4>>;

/// The model's code with these weights (the bytes of its .bpk file, checked
/// by the caller: wrong bytes make Burn panic).
fn forward(kind: Kind, weights: Vec<u8>, device: &Device) -> Forward {
    let bytes = Bytes::from_bytes_vec(weights);
    match kind {
        Kind::Fast => {
            let m = model::real_esrgan_general_x4v3::Model::from_bytes(bytes, device);
            Box::new(move |x| m.forward(x))
        }
        Kind::Quality => {
            let m = model::real_esrgan_x4plus::Model::from_bytes(bytes, device);
            Box::new(move |x| m.forward(x))
        }
    }
}

// ---- tiles: every call to the model gets the same shape, (TILE + 2 × PAD)
// square, with edge pixels repeated past the border, so the graphics chip's
// code is compiled and tuned once, not per tile size. --------------------------

struct Tiles {
    width: usize,
    height: usize,
    tile: usize,
    pad: usize,
}

impl Tiles {
    fn side(&self) -> usize {
        self.tile + 2 * self.pad
    }
    /// The tiles' top-left corners, row by row.
    fn corners(&self) -> Vec<(usize, usize)> {
        (0..self.height).step_by(self.tile).flat_map(|y| (0..self.width).step_by(self.tile).map(move |x| (x, y))).collect()
    }
    /// The area around the tile at (tx, ty), as 3 planes in 0..1. `px` is
    /// 3 (RGB) or 4 (RGBA, alpha ignored) bytes per pixel.
    fn read(&self, src: &[u8], px: usize, (tx, ty): (usize, usize)) -> Vec<f32> {
        let side = self.side();
        let mut planar = vec![0f32; 3 * side * side];
        for y in 0..side {
            let sy = (ty + y).saturating_sub(self.pad).min(self.height - 1);
            for x in 0..side {
                let sx = (tx + x).saturating_sub(self.pad).min(self.width - 1);
                let i = (sy * self.width + sx) * px;
                for c in 0..3 {
                    planar[c * side * side + y * side + x] = src[i + c] as f32 / 255.0;
                }
            }
        }
        planar
    }
    /// Copies the model's answer for one tile, without its padding, into `out`
    /// (the 4× picture, `px` bytes per pixel; alpha, if any, set to 255).
    fn write(&self, result: &[f32], out: &mut [u8], px: usize, (tx, ty): (usize, usize)) {
        let (s, ow) = (self.side() * SCALE, self.width * SCALE);
        let off = self.pad * SCALE; // the tile starts pad px in
        let (tw, th) = ((tx + self.tile).min(self.width) - tx, (ty + self.tile).min(self.height) - ty);
        for y in 0..th * SCALE {
            for x in 0..tw * SCALE {
                let o = ((ty * SCALE + y) * ow + tx * SCALE + x) * px;
                for c in 0..3 {
                    let v = result[c * s * s + (off + y) * s + off + x];
                    out[o + c] = (v.clamp(0.0, 1.0) * 255.0).round() as u8;
                }
                if px == 4 {
                    out[o + 3] = 255;
                }
            }
        }
    }
    fn tensor(&self, planar: Vec<f32>, device: &Device) -> Tensor<4> {
        let side = self.side();
        Tensor::<4>::from_data(TensorData::new(planar, [1, 3, side, side]), device)
    }
}

/// Upscales an RGB image (8-bit, row by row) 4× by running `forward` on tiles
/// of `tile` px, each read with `pad` px of its neighbours so the seams don't
/// show, and returns the RGB bytes of the result. Native only (it waits for the
/// graphics chip); a tab uses `web`.
#[cfg(not(target_family = "wasm"))]
pub fn upscale_rgb(
    rgb: &[u8],
    width: usize,
    height: usize,
    tile: usize,
    pad: usize,
    device: &Device,
    forward: impl Fn(Tensor<4>) -> Tensor<4>,
) -> Vec<u8> {
    let t = Tiles { width, height, tile, pad };
    let mut out = vec![0u8; width * SCALE * height * SCALE * 3];
    for corner in t.corners() {
        let result: Vec<f32> = forward(t.tensor(t.read(rgb, 3, corner), device)).into_data().try_to_vec::<f32>().expect("f32 output");
        t.write(&result, &mut out, 3, corner);
    }
    out
}

/// One model, loaded on the graphics chip. The first picture also compiles
/// and tunes the chip's code for the tile (3–6 s on an M2 Pro).
#[cfg(not(target_family = "wasm"))]
pub struct Upscaler {
    pub kind: Kind,
    device: Device,
    forward: Forward,
}

#[cfg(not(target_family = "wasm"))]
impl Upscaler {
    /// The model with its weights from `dir` (the file named by Kind::file),
    /// which the caller has checked against the pool's list.
    pub fn load(kind: Kind, dir: &std::path::Path) -> Result<Upscaler, String> {
        let weights = std::fs::read(dir.join(kind.file())).map_err(|_| format!("{} is not on this computer", kind.name()))?;
        let device = Device::default();
        let forward = forward(kind, weights, &device);
        Ok(Upscaler { kind, device, forward })
    }

    /// A PNG, JPEG or WebP file in, a JPEG 4× its size out, with that size.
    #[cfg(feature = "codec")]
    pub fn file(&self, bytes: &[u8]) -> Result<(Vec<u8>, u32, u32), String> {
        let img = image::load_from_memory(bytes).map_err(|e| format!("not a picture: {e}"))?.to_rgb8();
        let (w, h) = (img.width(), img.height());
        if w as u64 * h as u64 > MAX_PIXELS {
            return Err(format!("{w}×{h} is too big: at most {MAX_PIXELS} pixels"));
        }
        let rgb = upscale_rgb(img.as_raw(), w as usize, h as usize, TILE, PAD, &self.device, &self.forward);
        let (ow, oh) = (w * SCALE as u32, h * SCALE as u32);
        let mut out = Vec::new();
        image::codecs::jpeg::JpegEncoder::new_with_quality(&mut out, 90)
            .encode(&rgb, ow, oh, image::ExtendedColorType::Rgb8)
            .map_err(|e| e.to_string())?;
        Ok((out, ow, oh))
    }
}
